snippet_css:
:root{
  --bg: #F7F3FF;
  --fg: #3A2340;
  --muted: #5B4A6B;
  --surface: #FFFFFF;
  --border: #E7E1EE;
  --accent: #6B3FA0;
  --accent-fg: #FFFFFF;
  --accent-grad: linear-gradient(180deg,#8A5CC4,#6B3FA0);
  --radius: 30px;
  --radius-sm: 20px;
  --shadow: 0 12px 0 -4px rgba(58,35,64,.10),0 18px 28px rgba(58,35,64,.14),inset 0 -4px 0 rgba(58,35,64,.06);
  --btn-shadow: 0 6px 0 rgba(107,63,160,.35);
  --art-bg: linear-gradient(180deg,#E9F1FF,#B8E1FF 45%,#FFD6E0);
  --media-bg: linear-gradient(180deg,#FFE9A8,#FFB5C8);
  --cta-bg: linear-gradient(180deg,#C3F0CA,#B8E1FF);
  --input-bg: #FFFFFF;
  --ok: #1F7A45;
  --warn: #C2185B;
  --clay-pink: #FFD6E0;
  --clay-mint: #C3F0CA;
  --clay-sky: #B8E1FF;
  --clay-yellow: #FFE9A8;
  --font-display: 'Fredoka','Noto Sans TC',sans-serif;
  --font-body: 'Nunito','Noto Sans TC',sans-serif;
  --font-mono: 'Nunito',ui-monospace,monospace;
  --focus-ring: var(--accent);
}

